import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor gelu_cute_forward(torch::Tensor x);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <math.h>

#include <cute/tensor.hpp>

using namespace cute;

template <typename T, int Vec>
__global__ void gelu_kernel(const T* __restrict__ X,
                             T* __restrict__ Y,
                             int64_t N)
{
  const int64_t base = (int64_t)(blockIdx.x * blockDim.x + threadIdx.x) * Vec;
  if (base >= N) return;

  const int64_t remaining = N - base;
  const int n_valid = (int)(remaining < Vec ? remaining : (int64_t)Vec);

  // Local register buffer accessed via a CUTE tensor (owning register-resident tensor)
  Tensor rX = make_tensor<T>(make_shape(Int<Vec>{}));

  // Load (guarded) elements into the register tensor
  #pragma unroll
  for (int i = 0; i < Vec; ++i) {
    rX(i) = (i < n_valid) ? X[base + i] : T(0);
  }

  const float c0 = 0.5f;
  const float c1 = 0.7978845608028654f; // sqrt(2/pi)
  const float c2 = 0.044715f;

  #pragma unroll
  for (int i = 0; i < Vec; ++i) {
    float x  = (float)rX(i);
    float x3 = x * x * x;
    float inner = c1 * (x + c2 * x3);
    float t = tanhf(inner);
    rX(i) = (T)(c0 * x * (1.0f + t));
  }

  #pragma unroll
  for (int i = 0; i < Vec; ++i) {
    if (i < n_valid) {
      Y[base + i] = rX(i);
    }
  }
}

torch::Tensor gelu_cute_forward(torch::Tensor x) {
  TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");

  auto x_c = x.contiguous();
  auto y = torch::empty_like(x_c);

  int64_t N = x_c.numel();

  constexpr int Vec = 4;
  constexpr int Threads = 256;

  int64_t n_vec_threads = (N + Vec - 1) / Vec;
  int64_t blocks = (n_vec_threads + Threads - 1) / Threads;
  if (blocks < 1) blocks = 1;

  dim3 grid((unsigned int)blocks);
  dim3 block(Threads);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  gelu_kernel<float, Vec><<<grid, block, 0, stream>>>(
      x_c.data_ptr<float>(),
      y.data_ptr<float>(),
      N
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "gelu_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
"""

gelu_ext = load_inline(
    name="cute_gelu_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["gelu_cute_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include",
                          "/root/cutegen_test/cutegen/cutlass/include/cute/"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    GELU (tanh approximation) implemented as a single fused CUTE/CUDA kernel.
    """
    def __init__(self) -> None:
        super(ModelNew, self).__init__()
        self._ext = gelu_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.gelu_cute_forward(x)

